    "Første påske" to "Hvem var vi sammen med, og hvilke påsketraditioner prøvede du?",
    "Første fødselsdag" to "Hvordan fejrede vi dig, og hvad syntes du om kagen?",
)

internal fun bookStoryPrompts(title: String, chapter: String): List<String> {
    val prompts = storyPrompts[title] ?: when (chapter) {
        "De første gange" -> listOf("Hvor og hvornår skete det?", "Hvem var med og så det?", milestoneIdeas[title] ?: "Hvad gjorde du helt konkret?", "Hvordan reagerede vi?", "Hvad skete der i dagene op til og bagefter?")
        else -> listOf("Hvilke oplevelser forbinder vi med $title?", "Hvem var sammen med os?", "Hvad gjorde øjeblikket særligt?")
    }
    return listOf("Dato / alder") + prompts + "Andre minder og detaljer"
}
